// Burst — see specs/shared/n8n-workflows.md §6.
// Manual webhook: fires BURST_ORDER_COUNT orders (same composition logic as
// the order generator, §3.1-§3.2) at BURST_CONCURRENCY in parallel, and
// responds with the placed/refused counts and the order references.

const gatewayUrl = ($env.OTC_GATEWAY_URL || 'http://gateway:3001').replace(/\/$/, '');
const username = $env.GATEWAY_OPERATOR_USERNAME;
const password = $env.GATEWAY_OPERATOR_PASSWORD;
const timeoutMs = Number($env.OTC_REQUEST_TIMEOUT_MS || 10000);

const enabled = ($env.BURST_ENABLED ?? 'true') !== 'false';

const body = $input.first().json.body ?? {};
const orderCount = Number(body.count ?? $env.BURST_ORDER_COUNT ?? 20);
const compensationRatio = Number(body.compensationRatio ?? $env.BURST_COMPENSATION_RATIO ?? 0.2);
const concurrency = Number($env.BURST_CONCURRENCY || 5);
const maxLines = Number($env.ORDER_GENERATOR_MAX_LINES || 4);
const maxUnits = Number($env.ORDER_GENERATOR_MAX_UNITS || 10);

if (!enabled) {
  return [{ json: { enabled: false, message: 'BURST_ENABLED=false', placed: 0, refused: 0, orderReferences: [] } }];
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function requestWithRetry(options, { retryOn5xxAndNetwork = true } = {}) {
  const attempts = retryOn5xxAndNetwork ? 4 : 1;
  let lastErr;
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    try {
      return await this.helpers.httpRequest({ timeout: timeoutMs, ...options });
    } catch (err) {
      lastErr = err;
      const status = err.status ?? err.response?.status;
      const isNetworkError = status === undefined;
      const is5xx = typeof status === 'number' && status >= 500;
      if (!retryOn5xxAndNetwork || !(isNetworkError || is5xx) || attempt === attempts - 1) {
        throw err;
      }
      await sleep(2 ** attempt * 250);
    }
  }
  throw lastErr;
}

async function login() {
  const res = await requestWithRetry.call(this, {
    method: 'POST', url: `${gatewayUrl}/auth/login`, body: { username, password }, json: true,
  });
  return res.accessToken;
}

function authHeaders(token) {
  return { Authorization: `Bearer ${token}` };
}

async function loadCatalogue(token) {
  const headers = authHeaders(token);
  const [productsRes, retailersRes, companiesRes] = await Promise.all([
    requestWithRetry.call(this, { method: 'GET', url: `${gatewayUrl}/catalog/products`, headers, json: true }),
    requestWithRetry.call(this, { method: 'GET', url: `${gatewayUrl}/catalog/retailers`, headers, json: true }),
    requestWithRetry.call(this, { method: 'GET', url: `${gatewayUrl}/catalog/companies`, headers, json: true }),
  ]);
  return {
    products: productsRes.items.filter((p) => p.enabled),
    retailers: retailersRes.items.filter((r) => r.enabled),
    companies: companiesRes.items.filter((c) => c.enabled),
  };
}

function pick(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

function composeOrder(catalogue) {
  const retailer = pick(catalogue.retailers);
  const company = pick(catalogue.companies);
  const currency = retailer.currency;
  const eligibleProducts = catalogue.products.filter((p) => p.currency === currency);
  if (!eligibleProducts.length) return null;
  const lineCount = 1 + Math.floor(Math.random() * Math.max(1, maxLines));
  const lines = [];
  for (let i = 0; i < lineCount; i += 1) {
    const p = pick(eligibleProducts);
    lines.push({ productCode: p.code, quantity: 1 + Math.floor(Math.random() * Math.max(1, maxUnits)), unitPrice: p.price });
  }
  return { retailerCode: retailer.code, companyCode: company.code, currency, lines, notes: 'n8n burst' };
}

function orderTotal(order) {
  return order.lines.reduce((sum, l) => sum + l.unitPrice * l.quantity, 0);
}
function mod100(n) {
  return ((n % 100) + 100) % 100;
}
function engineerCompensation(order) {
  // Review fix (D1) — same fix as the order generator's identical function;
  // see its comment and progress/impl_n8n_workflows.md, "Review fixes".
  const lastLine = order.lines[order.lines.length - 1];
  lastLine.quantity = 1;
  const total = orderTotal(order);
  if (mod100(total) === 99) return true;
  const delta = mod100(99 - total); // 0..99, always reachable at quantity 1
  if (lastLine.unitPrice + delta < 1) return false; // defensive; unreachable with delta >= 0
  lastLine.unitPrice += delta;
  return mod100(orderTotal(order)) === 99;
}

async function placeOne(token, catalogue) {
  const order = composeOrder(catalogue);
  if (!order) return { outcome: 'skipped', reason: 'no eligible retailer/company/product combination' };
  if (compensationRatio > 0 && Math.random() < compensationRatio) engineerCompensation(order);
  try {
    const res = await requestWithRetry.call(this, {
      method: 'POST', url: `${gatewayUrl}/orders`, headers: authHeaders(token), body: order, json: true,
    });
    return { outcome: 'accepted', orderReference: res.orderReference };
  } catch (err) {
    const status = err.status ?? err.response?.status;
    if (status === 409 || status === 422) return { outcome: 'refused', status };
    throw err;
  }
}

// simple concurrency pool
async function runPool(tasks, poolSize) {
  const results = new Array(tasks.length);
  let next = 0;
  async function worker() {
    while (next < tasks.length) {
      const i = next;
      next += 1;
      results[i] = await tasks[i]();
    }
  }
  await Promise.all(Array.from({ length: Math.min(poolSize, tasks.length) }, worker));
  return results;
}

async function run() {
  const token = await login.call(this);
  const catalogue = await loadCatalogue.call(this, token);
  const tasks = Array.from({ length: Math.max(1, orderCount) }, () => () => placeOne.call(this, token, catalogue));
  const results = await runPool(tasks, Math.max(1, concurrency));
  const placed = results.filter((r) => r.outcome === 'accepted');
  const refused = results.filter((r) => r.outcome === 'refused');
  return {
    enabled: true,
    requested: orderCount,
    placed: placed.length,
    refused: refused.length,
    orderReferences: placed.map((r) => r.orderReference),
  };
}

const summary = await run.call(this);
return [{ json: summary }];
